<?php
require_once __DIR__.'/auth.php';admin_required();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');if($name!==''){$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-'));$slug.='-'.substr(bin2hex(random_bytes(2)),0,4);$s=$pdo->prepare("INSERT INTO categories(name,slug,description) VALUES(?,?,?)");$s->execute([$name,$slug,$desc]);$msg='Category added.';}}
$cats=$pdo->query("SELECT * FROM categories ORDER BY id")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Categories | AS NILORA</title><link rel="stylesheet" href="<?= e(url('assets/css/style.css')) ?>"></head><body><main class="section"><a href="<?= e(url('admin/index.php')) ?>">← Dashboard</a><h1>Manage categories</h1><?php if($msg): ?><p class="success-msg"><?= e($msg) ?></p><?php endif; ?><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>New category name<input name="name" required></label><label>Description<input name="description"></label><button class="btn btn-gold">Add category</button></form><div class="simple-list"><?php foreach($cats as $c): ?><div><strong><?= e($c['name']) ?></strong><span><?= e($c['slug']) ?></span></div><?php endforeach; ?></div></main></body></html>
